import { Water, type WaterProps } from "@paper-design/shaders-react";
import { forwardRef, useCallback, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { Interactive, Sequence, continueRender, delayRender, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

interface ShaderWaterProps extends Omit<WaterProps, "frame" | "ref"> {}

function ShaderWaterBase({
  speed = 1,
  colorBack = "#16202b",
  colorHighlight = "#5a6a7a",
  highlights = 0.06,
  waves = 0.3,
  caustic = 0.08,
  className,
  ...rest
}: ShaderWaterProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const [handle] = useState(() => delayRender("shader-water"));
  const gate = useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return;
      requestAnimationFrame(() =>
        requestAnimationFrame(() => continueRender(handle)),
      );
    },
    [handle],
  );

  return (
    <div
      ref={gate}
      className={className}
      style={{ position: "absolute", inset: 0 }}
    >
      <Water
        speed={0}
        frame={(frame / fps) * speed * 1000}
        colorBack={colorBack}
        colorHighlight={colorHighlight}
        highlights={highlights}
        waves={waves}
        caustic={caustic}
        fit="cover"
        width={width}
        height={height}
        {...rest}
      />
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  waves: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 0.3,
    description: "Waves",
    hiddenFromList: false,
  },
  caustic: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.02,
    default: 0.08,
    description: "Caustic",
    hiddenFromList: false,
  },
  highlights: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.02,
    default: 0.06,
    description: "Highlights",
    hiddenFromList: false,
  },
  colorBack: {
    type: "color",
    default: "#16202b",
    description: "Background",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["speed","waves","caustic","highlights","colorBack"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  speed: 1,
  waves: 0.3,
  caustic: 0.08,
  highlights: 0.06,
  colorBack: "#16202b",
};

type ShaderWaterElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ShaderWaterBase>;

const ShaderWaterInner = forwardRef<
  HTMLDivElement,
  ShaderWaterElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShaderWater>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ShaderWaterBase
          {...(componentProps as unknown as ComponentProps<typeof ShaderWaterBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ShaderWater = Interactive.withSchema({
  Component: ShaderWaterInner,
  componentName: "<ShaderWater>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
